 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]

    # Each nonzero connected component is one nested rectangular motif.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] != 0):
                        seen[ny][nx] = True
                        q.append((ny, nx))

            bounds = {}
            for y, x in cells:
                color = grid[y][x]
                if color not in bounds:
                    bounds[color] = [y, y, x, x]
                else:
                    b = bounds[color]
                    b[0] = min(b[0], y)
                    b[1] = max(b[1], y)
                    b[2] = min(b[2], x)
                    b[3] = max(b[3], x)

            # Nested colors are ordered from the broad outer layer to the
            # innermost layer by the area of each color's bounding rectangle.
            colors = sorted(bounds, key=lambda color: (
                -((bounds[color][1] - bounds[color][0] + 1) *
                  (bounds[color][3] - bounds[color][2] + 1)),
                -sum(1 for y, x in cells if grid[y][x] == color),
            ))
            remap = {old: new for old, new in zip(colors, reversed(colors))}
            for y, x in cells:
                out[y][x] = remap[grid[y][x]]

    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
